#!/usr/bin/env bash
# Generate the contract types from contracts/*.schema.json (spec Section 30): C++ structs with
# nlohmann/json serialisers for the engine's io thread, TypeScript types for the dashboard.
# CI runs this and fails on `git diff --exit-code`, so a schema change that is not regenerated —
# or a generated file edited by hand — cannot be merged.
#
#   ./scripts/gen-contracts.sh          (bash: Git Bash on Windows, any shell on Linux)
#
# Generator versions are pinned; bump them only together with the regenerated files.
set -euo pipefail
cd "$(dirname "$0")/.."

QUICKTYPE=quicktype@26.0.0
JSON2TS=json-schema-to-typescript@16.0.0

schemas=(contracts/state.schema.json contracts/anomaly.schema.json contracts/adjudication.schema.json
         contracts/health.schema.json contracts/host_health.schema.json)

mkdir -p control-app/include web/src/contracts

npx --yes "$QUICKTYPE" --src-lang schema --lang c++ \
  --namespace sunverify::contracts --code-format with-struct --include-location global-include \
  --no-boost --type-style pascal-case --member-style underscore-case --enumerator-style upper-underscore-case \
  -o control-app/include/contracts.hpp "${schemas[@]}"

for s in "${schemas[@]}"; do
  name=$(basename "$s" .schema.json)
  npx --yes -p "$JSON2TS" json2ts --input "$s" --output "web/src/contracts/$name.ts" \
    --cwd contracts --no-additionalProperties --bannerComment \
    "/* Generated from contracts/$name.schema.json by scripts/gen-contracts.sh. Do not edit. */"
done

{
  echo "/* Generated by scripts/gen-contracts.sh. Do not edit. */"
  for s in "${schemas[@]}"; do echo "export * from './$(basename "$s" .schema.json)';"; done
} > web/src/contracts/index.ts

# Line endings are LF everywhere, so the diff check behaves the same on Windows and Linux.
sed -i 's/\r$//' control-app/include/contracts.hpp web/src/contracts/*.ts
echo "contracts generated: control-app/include/contracts.hpp, web/src/contracts/"
